package com.glassbox.chess; import com.glassbox.chess.domain.*; import com.glassbox.chess.game.ChessGame; public final class TestMoves{private TestMoves(){}public static void play(ChessGame g,String from,String to)throws Exception{Position a=Position.fromAlgebraic(from),b=Position.fromAlgebraic(to);for(Move m:g.getLegalMovesFrom(a))if(m.getTo().equals(b)){g.makeMove(g.createCommand(m));return;}throw new AssertionError("Illegal test move: "+from+"-"+to);}}
